import{_ as t,c as r,a3 as o,o as n}from"./chunks/framework.mrTHZ8pa.js";const y=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"local/glossary.md","filePath":"local/glossary.md"}'),s={name:"local/glossary.md"};function a(i,e,l,c,g,d){return n(),r("div",null,e[0]||(e[0]=[o('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><ol><li><strong>Base Load</strong><br> The minimum level of demand over a span of time.</li><li><strong>Battery Management System (BMS)</strong><br> A system that manages the charging and discharging of batteries, ensuring safety, performance, and longevity.</li><li><strong>Emergency Stop Button</strong><br> A safety feature designed to halt operations immediately in the event of an emergency.</li><li><strong>Energy Management System (EMS)</strong><br> A system used to monitor, control, and optimize the performance of electrical generation, storage, and consumption within a facility.</li><li><strong>Energy Storage System (ESS)</strong><br> A system that stores energy for later use, typically consisting of batteries, inverters, and control systems.</li><li><strong>Grid Standard UL 480</strong><br> Refers to the UL 480 standard, a set of guidelines related to grid connectivity and safety for electrical systems.</li><li><strong>Over Frequency</strong><br> A situation where the frequency of the power supply exceeds its standard operating frequency, which can lead to system malfunctions.</li><li><strong>Over Voltage</strong><br> A condition where the voltage in an electrical circuit exceeds the specified voltage limit.</li><li><strong>Power Conversion System (PCS)</strong><br> Converts electrical power from one form to another (e.g., from AC to DC or vice versa) in energy storage systems.</li><li><strong>Solar Inverter</strong><br> A device that converts direct current (DC) electricity from solar panels into alternating current (AC) electricity for use in homes or businesses.</li><li><strong>State of Charge (SOC)</strong><br> The current level of battery charge, expressed as a percentage of the total capacity.</li><li><strong>Under Frequency</strong><br> Occurs when the frequency of the electrical supply falls below the standard operating frequency, causing potential instability.</li><li><strong>Under Voltage</strong><br> A condition where the voltage in an electrical circuit drops below the minimum threshold required for normal operations.</li></ol>',2)]))}const f=t(s,[["render",a]]);export{y as __pageData,f as default};
